async function openPartsQuotation(){if(!['Purchaser','Manager'].includes(role()))return;await hydrateAuthoritativeLists();if(!document.getElementById('v2SpQuotationFullStyle')){const st=document.createElement('style');st.id='v2SpQuotationFullStyle';st.textContent='#modal.v2-sp-modal-host:has(.v2-sp-quotation-page){inset:0!important;width:100vw!important;max-width:none!important;height:100dvh!important;max-height:none!important;border-radius:0!important;margin:0!important;padding:12px 14px!important;box-sizing:border-box!important;overflow-y:auto!important}.v2-sp-quotation-page{min-height:calc(100dvh - 24px);padding:6px!important}.v2-sp-quotation-page>h3{margin:4px 0 9px!important}.v2-sp-quotation-page>label{display:block;font-weight:800}.v2-sp-quotation-page>label input{width:100%;margin-top:5px;box-sizing:border-box}.v2-sp-quotation-page .v2-sp-quote-result{min-height:52px!important;margin:5px 0!important;padding:6px 9px!important;border-radius:11px!important}.v2-sp-quotation-detail .v2-sp-quote-card{padding:8px!important;margin:6px 0!important;border-radius:11px!important}.v2-sp-quotation-detail .v2-sp-quote-part strong{white-space:normal!important;line-height:1.18}.v2-sp-quotation-detail .v2-sp-quote-dense-entry{gap:5px!important}.v2-sp-quotation-detail .v2-sp-offer{position:relative}.v2-sp-quotation-detail .v2-sp-offer.selected:after{content:" · Selected";font-weight:900}.v2-sp-quotation-detail .v2-sp-quote-total{position:sticky;bottom:0;z-index:2;box-shadow:0 -3px 12px #17304d14}.v2-sp-quotation-detail .v2-pl-tools{position:sticky;bottom:48px;z-index:2;background:#f5f9fd;padding:6px 0}.v2-sp-change-offer{font-size:10px!important;padding:4px 7px!important}@media(max-width:430px){.v2-sp-quotation-page{padding:3px!important}.v2-sp-quotation-detail .v2-sp-quote-entry input{min-width:0!important}.v2-sp-quotation-detail .v2-pl-tools button{font-size:12px!important}}';document.head.appendChild(st)}openSpareModal(withNav('<div class="v2-sp-purchaser v2-sp-dashboard v2-sp-quotation-page"><h3>Parts Quotation</h3><label>Find Parts List by PL, JC or registration<input id="v2SpQuotationSearch" type="search" placeholder="PL001 / JC120 / registration" oninput="zukaitV2.sparePartsMain.findPartsQuotation()"></label><div id="v2SpQuotationResults"></div></div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal();findPartsQuotation()}
function findPartsQuotation(){const q=String(document.getElementById('v2SpQuotationSearch')?.value||'').trim().toLowerCase(),host=document.getElementById('v2SpQuotationResults');if(!host)return;const matching=read().filter(r=>(r.items||[]).length&&(!q||[r.listNo,r.jobCard,r.registration,r.vehicle,r.model,r.year].some(v=>String(v||'').toLowerCase().includes(q)))).slice(0,50);host.innerHTML=matching.map((r,i)=>'<button type="button" class="v2-sp-quote-result" data-list="'+esc(r.listNo)+'" onclick="zukaitV2.sparePartsMain.quotationListClick(this)"><span class="v2-sp-index">'+(i+1)+'</span><span class="v2-sp-quote-result-main"><b>'+esc(r.listNo)+' · JC '+esc(r.jobCard)+'</b><strong>'+esc([r.vehicle,r.model,r.year].filter(Boolean).join(' ')||'Vehicle pending')+'</strong><small>Reg '+esc(r.registration||'—')+'</small></span><span class="v2-sp-quote-result-count">'+r.items.length+' Parts</span></button>').join('')||'<p class="muted">No matching Parts List found.</p>'}
function quotationListClick(button){const no=button?.dataset?.list;if(no)openQuotationList(no)}
function partCategory(name){const s=normalizedPartName(name);if(/bumper|fender|bonnet|hood|door|grill|grille|mirror|lamp|light|panel|glass|windshield|boot|trunk|spoiler/.test(s))return 'Body';if(/engine|mount|brake|disc|pad|shock|arm|bearing|radiator|pump|belt|filter|clutch|gear|axle|hub|suspension/.test(s))return 'Mechanical';if(/sensor|switch|wiring|wire|battery|ecu|module|motor|camera|radar|speaker|alternator|starter/.test(s))return 'Electrical';if(/clip|screw|bolt|nut|sealant|adhesive|tape|grease|oil|coolant|fluid/.test(s))return 'Consumables';return 'Other'}
function partsLibrary(query='',list=null){const q=normalizedPartName(query),map=new Map();for(const r of read()){for(const x of r.items||[]){const name=String(x.name||'').trim();if(!name)continue;const key=String(x.partNo||'').trim().toUpperCase()||normalizedPartName(name);if(!key)continue;const e=map.get(key)||{name,partNo:String(x.partNo||''),category:partCategory(name),uses:0,suppliers:new Set(),lastPrice:null,lastAt:''};e.uses++;if(x.supplier)e.suppliers.add(String(x.supplier));const price=validMoney(x.purchaseAmount??x.quoteAmount),at=x.updatedAt||x.createdAt||r.updatedAt||r.createdAt||'';if(price!=null&&Date.parse(at||0)>=Date.parse(e.lastAt||0)){e.lastPrice=price;e.lastAt=at}map.set(key,e)}}return [...map.values()].filter(x=>!q||normalizedPartName(x.name).includes(q)||String(x.partNo||'').toLowerCase().includes(q)).sort((a,b)=>b.uses-a.uses||a.name.localeCompare(b.name)).slice(0,8)}
function draftPartSuggestions(){const host=document.getElementById('v2SpDraftSuggestions'),input=document.getElementById('v2SpDraftName');if(!host||!input)return;const rows=partsLibrary(input.value);host.innerHTML=rows.map(x=>'<button type="button" class="v2-sp-part-suggest" data-name="'+esc(x.name)+'" onclick="zukaitV2.sparePartsMain.usePartSuggestion(this)"><b>'+esc(x.name)+'</b><small>'+esc(x.category)+(x.lastPrice!=null?' · Last '+x.lastPrice.toFixed(3):'')+'</small></button>').join('')}
function usePartSuggestion(button){const input=document.getElementById('v2SpDraftName');if(!input)return;input.value=String(button.dataset.name||'');document.getElementById('v2SpDraftQty')?.focus();const host=document.getElementById('v2SpDraftSuggestions');if(host)host.innerHTML=''}
function normalizedPartName(v){return String(v||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim()}
function partPriceHistory(list,item){const key=normalizedPartName(item?.name),partNo=String(item?.partNo||'').trim().toUpperCase(),matches=[];for(const r of read()){for(const x of r.items||[]){if(String(x.id)===String(item?.id))continue;const sameNo=partNo&&String(x.partNo||'').trim().toUpperCase()===partNo,sameName=key&&normalizedPartName(x.name)===key;if(!sameNo&&!sameName)continue;const price=validMoney(x.purchaseAmount??x.quoteAmount);if(price==null)continue;matches.push({price,supplier:String(x.supplier||''),at:x.updatedAt||x.createdAt||r.updatedAt||r.createdAt||''})}}matches.sort((a,b)=>Date.parse(b.at||0)-Date.parse(a.at||0));if(!matches.length)return null;const last=matches[0],lowest=matches.reduce((a,b)=>b.price<a.price?b:a,matches[0]);return {last,lowest,count:matches.length}}
function supplierSuggestions(item){const key=normalizedPartName(item?.name),partNo=String(item?.partNo||'').trim().toUpperCase(),seen=new Map();for(const r of read()){for(const x of r.items||[]){const supplier=String(x.supplier||'').trim();if(!supplier)continue;const sameNo=partNo&&String(x.partNo||'').trim().toUpperCase()===partNo,sameName=key&&normalizedPartName(x.name)===key;if(!sameNo&&!sameName)continue;const price=validMoney(x.purchaseAmount??x.quoteAmount),prev=seen.get(supplier);if(!prev||Date.parse(x.updatedAt||x.createdAt||0)>Date.parse(prev.at||0))seen.set(supplier,{supplier,price,at:x.updatedAt||x.createdAt||''})}}return [...seen.values()].sort((a,b)=>Date.parse(b.at||0)-Date.parse(a.at||0)).slice(0,3)}
function quotationHistoryHint(list,item,index){const h=partPriceHistory(list,item),vendors=supplierSuggestions(item);if(!h&&!vendors.length)return '';const current=validMoney(item?.quoteAmount),delta=h&&current!=null?current-h.last.price:null,change=delta==null||Math.abs(delta)<0.0005?'':('<span class="v2-sp-price-change '+(delta>0?'up':'down')+'">'+(delta>0?'▲ ':'▼ ')+Math.abs(delta).toFixed(3)+' vs last</span>'),last=h?'<span>Last <b>'+h.last.price.toFixed(3)+'</b>'+(h.last.supplier?' · '+esc(h.last.supplier):'')+'</span>':'',low=h?'<span>Lowest <b>'+h.lowest.price.toFixed(3)+'</b>'+(h.lowest.supplier?' · '+esc(h.lowest.supplier):'')+'</span>':'',chips=vendors.map(v=>'<button type="button" class="v2-sp-vendor-chip" data-index="'+index+'" data-vendor="'+esc(v.supplier)+'" onclick="zukaitV2.sparePartsMain.useSupplierSuggestion(this)">'+esc(v.supplier)+(v.price!=null?' '+v.price.toFixed(3):'')+'</button>').join('');return '<div class="v2-sp-price-history">'+last+low+change+(chips?'<span class="v2-sp-vendor-chips">'+chips+'</span>':'')+'</div>'}
function useSupplierSuggestion(button){const i=button?.dataset?.index,field=document.getElementById('v2SpVendor_'+i);if(!field)return;field.value=String(button.dataset.vendor||'');document.getElementById('v2SpQuote_'+i)?.focus()}
function quotationOffers(item){return Array.isArray(item?.quotationOffers)?item.quotationOffers.filter(x=>x&&validMoney(x.amount)!=null&&String(x.supplier||'').trim()):[]}
function quotationOffersHtml(list,item,index){const offers=quotationOffers(item);if(!offers.length)return '<div class="v2-sp-offers-empty">No vendor quotations saved</div>';return '<div class="v2-sp-offers">'+offers.map((o,j)=>{const selected=String(item.supplier||'')===String(o.supplier||'')&&Number(item.quoteAmount)===Number(o.amount);return '<button type="button" class="v2-sp-offer '+(selected?'selected':'')+'" data-list="'+esc(list.listNo)+'" data-item="'+esc(item.id)+'" data-index="'+index+'" data-offer="'+j+'" data-change="'+(item.quoteAmount!=null&&!selected?'1':'0')+'" onclick="zukaitV2.sparePartsMain.selectQuotationOffer(this)">'+esc(o.supplier)+' <b>'+Number(o.amount).toFixed(3)+' OMR</b></button>'}).join('')+'</div>'}
