function draftSubmissionKey(d){if(d.submitKey)return d.submitKey;d.submitKey=(crypto?.randomUUID?.()||('sp-'+Date.now()+'-'+Math.random().toString(36).slice(2)));draftSave(d);return d.submitKey}
function draftCustomer(value){const d=draftRead();d.customer=String(value||'').trim();draftSave(d)}
function draftAdd(){const d=draftRead(),name=String(document.getElementById('v2SpDraftName')?.value||'').trim(),qty=validQty(document.getElementById('v2SpDraftQty')?.value);if(!d.jobCard)return draftMessage('Find a Job Card first.');if(!name||qty==null)return draftMessage('Enter a part name and a valid quantity.');d.items=d.items||[];const previous=d.items.find((x,i)=>i!==d.editIndex&&partKey(x.name)===partKey(name));if(previous){draftMessage('Part already listed. Edit its quantity below.');return}if(Number.isInteger(d.editIndex)&&d.items[d.editIndex]){d.items[d.editIndex]={name,qty};delete d.editIndex}else d.items.push({name,qty});draftSave(d);document.getElementById('v2SpDraftName').value='';document.getElementById('v2SpDraftQty').value='1';draftRender();document.getElementById('v2SpDraftName')?.focus();draftMessage('Part added.')}
function draftEdit(i){const d=draftRead(),x=d.items?.[i];if(!x)return;document.getElementById('v2SpDraftName').value=x.name;document.getElementById('v2SpDraftQty').value=x.qty;d.editIndex=i;draftSave(d);draftMessage('Update the part above and press Add.')}
function draftDelete(i){const d=draftRead();if(!d.items?.[i])return;const removed=d.items.splice(i,1)[0];delete d.editIndex;draftSave(d);draftRender();draftMessage('Removed '+removed.name+'.');}
function managerCreatePanel(){if(!canManage())return;ensureSparePartsUiStyle();const d=draftRead();openSpareModal(withNav('<div class="v2-sp-manager-create" style="background:#f5f9fd;color:#173651;padding:15px;border-radius:17px"><div class="v2-sp-create-title"><h3 style="margin:0">Create Parts List</h3></div><div class="v2-sp-search"><input id="v2SpareJob" value="'+esc(d.jobCard||'')+'" placeholder="Job Card number" aria-label="Find Job Card"><button type="button" onclick="zukaitV2.sparePartsMain.draftFind()" style="'+spareBtn('primary')+'">Find Job Card</button></div><div id="v2SpDraftDetails"></div><h4>Add Part</h4><div class="v2-sp-addrow"><label class="v2-sp-part-entry"><span>Item</span><input id="v2SpDraftName" placeholder="Part name" aria-label="Item" oninput="zukaitV2.sparePartsMain.draftPartSuggestions()"><div id="v2SpDraftSuggestions" class="v2-sp-part-suggestions"></div></label><label class="v2-sp-qty-entry"><span>Qty</span><input id="v2SpDraftQty" type="number" min="1" value="1" aria-label="Quantity"></label><button type="button" onclick="zukaitV2.sparePartsMain.draftAdd()" style="'+spareBtn('primary')+'">＋ Add</button></div><h4>Parts to send <small id="v2SpDraftCount"></small></h4><div id="v2SpDraftRows" class="v2-sp-draft-list"></div><button id="v2SpDraftCreate" type="button" onclick="zukaitV2.sparePartsMain.createFromUI()" style="'+spareBtn('success')+';width:100%;margin-top:14px">Create Parts List</button><p id="v2SpDraftMessage" role="status" aria-live="polite"></p></div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal();draftRender()}
function partFullyArrived(item){const status=String(item?.status||'').toUpperCase(),qty=Number(item?.qty||0),received=Number(item?.receivedQty||0);if(status==='RECEIVED')return Number.isFinite(qty)&&qty>0&&Number.isFinite(received)&&received>=qty;return !!item?.arrivalAccepted||['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(status)}
const NEW_PARTS_WORK_HOURS=27;
const SPARE_PARTS_WORKSHOP_SCHEDULE=Object.freeze({workPeriods:[[8,13],[15,19]],closedWeekdays:[5]});
function sparePartsPublicHoliday(ts){try{if(window.zukaitV2?.rules?.publicHoliday)return !!window.zukaitV2.rules.publicHoliday(window.state||{},ts)}catch(_){}const d=new Date(ts),key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),state=window.state||{},rows=state.workshopHolidays||state.holidays||state.publicHolidays||[];return rows.some(h=>String(typeof h==='object'?(h.date||h.dateKey||h.day||''):h).slice(0,10)===key)}
function newPartsWorkingAgeHours(list,now=Date.now()){let t=Date.parse(list?.createdAt||list?.created_at||'');if(!Number.isFinite(t)||t>=now)return 0;let hours=0,guard=0;const periods=SPARE_PARTS_WORKSHOP_SCHEDULE.workPeriods,closed=new Set(SPARE_PARTS_WORKSHOP_SCHEDULE.closedWeekdays);while(t<now&&hours<NEW_PARTS_WORK_HOURS&&guard<120){const d=new Date(t),day=d.getDay(),h=d.getHours()+d.getMinutes()/60;if(!closed.has(day)&&!sparePartsPublicHoliday(t)){let end=null;if(h<periods[0][0])t=new Date(d.getFullYear(),d.getMonth(),d.getDate(),periods[0][0],0,0,0).getTime();else if(h<periods[0][1])end=new Date(d.getFullYear(),d.getMonth(),d.getDate(),periods[0][1],0,0,0).getTime();else if(h<periods[1][0])t=new Date(d.getFullYear(),d.getMonth(),d.getDate(),periods[1][0],0,0,0).getTime();else if(h<periods[1][1])end=new Date(d.getFullYear(),d.getMonth(),d.getDate(),periods[1][1],0,0,0).getTime();else t=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1,periods[0][0],0,0,0).getTime();if(end){const stop=Math.min(end,now);hours+=(stop-t)/3600000;t=end}}else t=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1,periods[0][0],0,0,0).getTime();guard++}return Math.max(0,hours)}
function isNewPartsList(list){const created=Date.parse(list?.createdAt||list?.created_at||'');return Number.isFinite(created)&&created<=Date.now()&&newPartsWorkingAgeHours(list)<NEW_PARTS_WORK_HOURS}
function managerListMatches(r,bucket){const items=r.items||[],statuses=items.map(i=>String(i.status||'LISTED'));if(bucket==='ALL')return true;if(bucket==='NEW')return isNewPartsList(r)&&items.length>0&&items.every(i=>['LISTED','ENQUIRY','QUOTED'].includes(String(i.status||'LISTED').toUpperCase()));if(bucket==='WAITING')return items.length>0&&!items.every(partFullyArrived);if(bucket==='ATTENTION')return items.some(i=>['RETURNED','UNAVAILABLE'].includes(i.status)||i.cashSettlementRequired);if(bucket==='PURCHASE_COMPLETED')return items.length>0&&items.every(arrivedConfirmed)&&items.every(i=>Number.isFinite(Number(i.purchaseAmount))&&Number(i.purchaseAmount)>0);if(bucket==='DELIVERED_PENDING'){const delivered=job(r.jobCard)?.delivered===true;return (r.vehicleDeliveredPartsPending===true||r.deliveryPartsPending===true||r.deliveredPendingParts===true||String(r.status||'').toUpperCase()==='DELIVERED_PENDING'||delivered)&&items.some(isDeliveredVehiclePartPending)}return statuses.some(s=>bucket==='RECEIVED'?['RECEIVED','SUPERVISOR_VERIFIED'].includes(s):s===bucket)}
function invoiceAmountEligible(item){return arrivedConfirmed(item)}
function invoicePriceMissing(item){const n=Number(item?.purchaseAmount);return item?.purchaseAmount==null||!Number.isFinite(n)||n<=0}
function invoiceMissingItems(rows=read()){return rows.flatMap(list=>(list.items||[]).filter(item=>invoiceAmountEligible(item)&&invoicePriceMissing(item)).map(item=>({list,item})))}
function ensureInvoiceEntryStyle(){ensureSpareStatusFullPageStyle();if(document.getElementById('v2SpInvoiceEntryStyle'))return;const st=document.createElement('style');st.id='v2SpInvoiceEntryStyle';st.textContent='.v2-sp-invoice-search{display:block;font-weight:850;margin:8px 0}.v2-sp-invoice-search input{width:100%;box-sizing:border-box;margin-top:4px;min-height:40px}.v2-sp-invoice-head,.v2-sp-invoice-row{display:grid;grid-template-columns:32px minmax(0,1fr) 46px minmax(142px,.8fr);gap:8px;align-items:center}.v2-sp-invoice-head{padding:5px 7px;font-size:9px;font-weight:900;color:#60748d}.v2-sp-invoice-row{margin:7px 0;padding:10px;background:#fff;border:1px solid #dbe5f0;border-left:4px solid #39739f;border-radius:14px;box-shadow:0 3px 10px #17304d12;font-size:13px}.v2-sp-invoice-row strong{font-size:18px!important;line-height:1.18!important;color:#102f50!important;font-weight:950!important}.v2-sp-invoice-row small{display:block;color:#60748d}.v2-sp-invoice-row input{width:78px;min-width:0;box-sizing:border-box;padding:8px 7px!important;min-height:40px!important;font-size:15px!important;font-weight:850!important;text-align:right}.v2-sp-invoice-pricecell,.v2-sp-invoice-price-action{display:flex!important;flex-direction:row!important;align-items:center!important;justify-content:flex-end!important;gap:6px!important;white-space:nowrap!important;min-width:0}.v2-sp-invoice-price-action input{flex:0 0 78px!important}.v2-sp-invoice-price-action button{flex:0 0 auto!important;margin:0!important}.v2-sp-invoice-omr{font-size:10px;font-weight:900;color:#60748d}.v2-sp-invoice-save{width:auto!important;min-width:58px!important;min-height:40px!important;padding:6px 9px!important;border-radius:10px!important;font-size:12px!important}.v2-sp-invoice-agreed{text-align:right;font-weight:850}.v2-sp-invoice-vendor{overflow-wrap:anywhere}.v2-sp-invoice-empty{padding:28px 12px;text-align:center;color:#60748d;font-weight:750}@media(max-width:430px){.v2-sp-invoice-head,.v2-sp-invoice-row{grid-template-columns:28px minmax(0,1fr) 34px minmax(132px,.9fr);gap:5px}.v2-sp-invoice-head{font-size:8px}.v2-sp-invoice-row{padding:6px 5px;font-size:10px}.v2-sp-invoice-save{font-size:10px!important;padding:4px!important}}';document.head.appendChild(st)}
async function openInvoiceEntry(){if(!['Supervisor','Manager'].includes(role()))return;ensureInvoiceEntryStyle();await hydrateAuthoritativeLists();const groups=new Map();for(const x of invoiceMissingItems()){if(!groups.has(x.list.listNo))groups.set(x.list.listNo,{list:x.list,items:[]});groups.get(x.list.listNo).items.push(x.item)}const groupsArray=[...groups.values()];const rows=groupsArray.map((x,i)=>'<button type="button" class="v2-compact-list-row v2-sp-invoice-index" data-search="'+esc([x.list.listNo,x.list.jobCard,x.list.registration,x.list.vehicle,x.list.model].join(' ').toLowerCase())+'" data-list="'+esc(x.list.listNo)+'" onclick="zukaitV2.sparePartsMain.openInvoiceEntryList(this.dataset.list)"><b class="v2-row-no">'+(i+1)+'</b><span><strong>'+esc(x.list.listNo)+' · JC '+esc(x.list.jobCard)+'</strong></span><span>'+esc([x.list.vehicle,x.list.model,x.list.year].filter(Boolean).join(' ')||'Vehicle')+'</span><span>'+x.items.length+' pending</span><span class="v2-row-reg">'+esc(x.list.registration||'—')+'</span><b class="v2-row-next">›</b></button>').join('')||'<div class="v2-sp-invoice-empty">✓ No parts waiting for invoice price review.</div>';openSpareModal(withNav('<div class="v2-sp-dashboard v2-sp-status-full"><h3>🧾 Invoice Entry</h3><p class="muted">Supervisor-confirmed arrived parts with missing or zero final invoice price. Enter a valid amount to complete the purchase.</p><label class="v2-sp-invoice-search">Search by JC / PL / Registration<input id="v2SpInvoiceSearch" type="search" placeholder="Job Card, PL number or registration" oninput="zukaitV2.sparePartsMain.invoiceSearchRows()"></label><div id="v2SpInvoiceRows">'+rows+'</div></div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal()}
function invoiceSearchRows(){const q=String(document.getElementById('v2SpInvoiceSearch')?.value||'').trim().toLowerCase();document.querySelectorAll('#v2SpInvoiceRows .v2-sp-invoice-index').forEach(el=>{el.style.display=!q||String(el.dataset.search||'').includes(q)?'':'none'})}
async function openInvoiceEntryList(listNo){if(!['Supervisor','Manager'].includes(role()))return;ensureInvoiceEntryStyle();await hydrateAuthoritativeLists();const list=read().find(x=>String(x.listNo)===String(listNo));if(!list)return alert('Parts List not found.');const items=(list.items||[]).filter(item=>invoiceAmountEligible(item)&&invoicePriceMissing(item));const body=items.map((item,i)=>'<div class="v2-sp-invoice-row"><b class="v2-row-no">'+(i+1)+'</b><span><strong>'+esc(item.name||'Part')+'</strong>'+(item.partNo?'<small>'+esc(item.partNo)+'</small>':'')+'</span><b>×'+esc(item.qty||1)+'</b><span class="v2-sp-invoice-price-action"><input type="number" min="0.001" step="0.001" inputmode="decimal" id="v2SpInvoicePrice_'+i+'" placeholder="0.000" aria-label="Final invoice price OMR for '+esc(item.name||'Part')+'"><button type="button" class="v2-sp-invoice-save" data-list="'+esc(list.listNo)+'" data-item="'+esc(item.id)+'" data-input="v2SpInvoicePrice_'+i+'" onclick="zukaitV2.sparePartsMain.invoiceEntryClick(this)" style="'+spareBtn('success')+'">✓ Save</button></span></div>').join('')||'<div class="v2-sp-invoice-empty">✓ All eligible parts on this Job Card have invoice amounts.</div>';const vehicle=[vehicleLabelForList(list),job(list.jobCard)?.year||list.year].filter(Boolean).join(' ');openSpareModal(withNav('<div class="v2-pl-detail v2-sp-status-full"><div class="v2-pl-hero v2-pl-hero-compact"><div class="v2-pl-hero-line"><strong>🧾 '+esc(list.listNo)+' · JC '+esc(list.jobCard)+'</strong><span>🚗 '+esc(vehicle||'Vehicle')+'</span><b>'+items.length+' Pending</b></div><div class="v2-pl-meta"><span>Reg '+esc(list.registration||'—')+'</span><span>INVOICE ENTRY</span></div></div><div class="v2-sp-invoice-head"><span>No.</span><span>Part</span><span>Qty</span><span>Final Price OMR</span></div>'+body+'</div>','zukaitV2.sparePartsMain.openInvoiceEntry()'));markSparePartsModal()}
async function invoiceEntryClick(button){const listNo=button?.dataset?.list,itemId=button?.dataset?.item,inputId=button?.dataset?.input;if(!listNo||!itemId)return;const input=document.getElementById(inputId),raw=input?.value;if(raw==null||String(raw).trim()==='')return alert('Enter the final invoice price.');const price=Number(raw);if(!Number.isFinite(price)||price<=0)return alert('Final invoice price must be more than 0.000 OMR.');const result=await saveSupervisorInvoicePrice(listNo,itemId,'invoice',price);if(result?.ok)return openInvoiceEntryList(listNo)}
async function renderSupervisorDashboard(){ensureSparePartsUiStyle();ensureSharedSpareDashboardStyle();const rows=await hydrateAuthoritativeLists(),attention=attentionForRole(rows,'Supervisor').length,sum=managerDashboardSummary(rows),cards=[['📝','Create Parts List','New PL','CREATE'],['NEW','New Parts List',rows.filter(r=>managerListMatches(r,'NEW')).length,'NEW'],['📋','Parts List',rows.length,'ALL'],['📦','Parts Arrived',arrivalPendingCount(rows),'ARRIVAL_CONFIRM'],['⏳','Parts Waiting',sum.waiting,'WAITING'],['🔎','Parts Pending',pendingSummary(rows).parts,'PENDING'],['✓','Purchase Completed',sum.purchaseCompleted,'PURCHASE_COMPLETED'],['🚗','Delivered Vehicle – Pending Parts',sum.deliveredPending,'DELIVERED_PENDING'],['🧾','Invoice Entry',invoiceMissingItems(rows).length,'INVOICE']];const recent=spareRecentRows(rows,5);const operational=cards.map((x,i)=>'<button class="v2-sp-tile v271-sp-card-'+i+'" data-count-state="'+(Number(x[2])>0?'active':'empty')+'" onclick="'+(x[3]==='CREATE'?'zukaitV2.sparePartsMain.managerCreatePanel()':x[3]==='PENDING'?'zukaitV2.sparePartsMain.openPartsPending()':x[3]==='ARRIVAL_CONFIRM'?'zukaitV2.sparePartsMain.openArrivalConfirmation()':x[3]==='INVOICE'?'zukaitV2.sparePartsMain.openInvoiceEntry()':"zukaitV2.sparePartsMain.managerBucket('"+x[3]+"')")+'"><span class="v271-sp-icon">'+x[0]+'</span><b class="v271-sp-label">'+x[1]+'</b><strong class="v271-sp-count">'+x[2]+'</strong></button>').join('');openSpareModal(withNav('<div class="v2-sp-manager v2-sp-dashboard v2-sp-shared-home">'+spareDashboardHeader('Supervisor','v2SpManagerSearch','managerSearch')+'<button class="v2-sp-attention" style="'+dashboardTile(attention?'wait':'neutral')+'" onclick="zukaitV2.sparePartsMain.openAttention()">⚠ Parts Attention <strong style="float:right;font-size:18px">'+attention+'</strong></button><div class="v2-sp-grid2" style="margin-top:9px">'+operational+'</div><h4 style="margin:12px 0 5px">Recent Activity</h4>'+recent+'</div>','',true));markSparePartsModal()}
async function renderManagerDashboard(){ensureSparePartsUiStyle();ensureSharedSpareDashboardStyle();const rows=await hydrateAuthoritativeLists(),sum=managerDashboardSummary(rows),cards=[['📝','Create Parts List','New PL','CREATE'],['🆕','New Parts List',rows.filter(r=>managerListMatches(r,'NEW')).length,'NEW'],['📋','Parts List',rows.length,'ALL'],['📦','Parts Arrived',arrivalPendingCount(rows),'ARRIVAL_CONFIRM'],['⏳','Parts Waiting',sum.waiting,'WAITING'],['🔎','Parts Pending',pendingSummary(rows).parts,'PENDING'],['✅','Purchase Completed',sum.purchaseCompleted,'PURCHASE_COMPLETED'],['🚗','Delivered Vehicle – Pending Parts',sum.deliveredPending,'DELIVERED_PENDING'],['🧾','Invoice Entry',invoiceMissingItems(rows).length,'INVOICE']];const recent=spareRecentRows(rows,5);const summary='<div class="v2-sp-grid2 v2-sp-summary" style="margin-top:12px"><div class="notice"><b>⚠ Parts Attention</b><div class="stat">'+sum.attention+'</div></div><div class="notice"><b>⏳ Parts Waiting</b><div class="stat">'+sum.waiting+'</div></div><div class="notice"><b>🚗 Delivered – Pending</b><div class="stat">'+sum.deliveredPending+'</div></div><div class="notice"><b>💰 Month Purchase</b><div class="stat">'+sum.monthSpend.toFixed(3)+' OMR</div></div></div>';const operational=cards.map(x=>{const kind=x[3]==='CREATE'?'primary':x[3]==='WAITING'?'wait':x[3]==='PURCHASE_COMPLETED'?'success':x[3]==='DELIVERED_PENDING'?'danger':x[3]==='NEW'?'info':'neutral';return '<button class="v2-sp-tile'+(x[3]==='ARRIVAL_CONFIRM'?' v2-sp-arrival-tile':'')+'" data-count-state="'+(Number(x[2])>0?'active':'empty')+'" style="'+dashboardTile(kind)+'" onclick="'+(x[3]==='CREATE'?'zukaitV2.sparePartsMain.managerCreatePanel()':x[3]==='PENDING'?'zukaitV2.sparePartsMain.openPartsPending()':x[3]==='ARRIVAL_CONFIRM'?'zukaitV2.sparePartsMain.openArrivalConfirmation()':x[3]==='INVOICE'?'zukaitV2.sparePartsMain.openInvoiceEntry()':"zukaitV2.sparePartsMain.managerBucket('"+x[3]+"')")+'"><span style="font-size:22px">'+x[0]+'</span><b style="display:block;margin-top:5px">'+x[1]+'</b><strong style="font-size:19px">'+x[2]+'</strong></button>'}).join('');openSpareModal(withNav('<div class="v2-sp-manager v2-sp-dashboard v2-sp-shared-home">'+spareDashboardHeader('Manager','v2SpManagerSearch','managerSearch')+''+summary+'<h4 style="margin:14px 0 7px">Operations</h4><div class="v2-sp-grid2">'+operational+'</div><h4 style="margin:14px 0 7px">Manager Controls</h4><div class="v2-sp-grid2"><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.openPartsQuotation()">🧾 Parts Quotation</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.openManagerReport()">📊 Reports</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.managerBucket(\'ALL\')">✏️ View / Edit</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.managerBucket(\'ATTENTION\')">⚠ Attention '+sum.attention+'</button><button class="v2-sp-tile v2-sp-control" onclick="zukaitV2.sparePartsMain.managerBucket(\'ALL\')">📚 History / Audit</button></div><h4 style="margin:14px 0 6px">Recent Activity</h4>'+recent+'</div>','',true))}
let activePartsBucket='ALL';
function partsBucketRows(){const q=String(document.getElementById('v2SpBucketSearch')?.value||'').trim().toLowerCase(),host=document.getElementById('v2SpBucketRows');if(!host)return;const rows=read().filter(r=>managerListMatches(r,activePartsBucket)).sort((a,b)=>Date.parse(b.createdAt||b.updatedAt||0)-Date.parse(a.createdAt||a.updatedAt||0)).filter(r=>!q||[r.listNo,r.jobCard,r.registration,r.vehicle,r.model,r.year].some(x=>String(x||'').toLowerCase().includes(q)));host.innerHTML=rows.slice(0,200).map((r,i)=>'<button type="button" class="v2-compact-list-row" data-list="'+esc(r.listNo)+'" onclick="zukaitV2.sparePartsMain.bucketOpen(this)"><b class="v2-row-no">'+(i+1)+'</b><span><strong>'+esc(r.listNo)+'</strong></span><span>JC '+esc(r.jobCard)+'</span><span>'+esc([r.vehicle,r.model,r.year].filter(Boolean).join(' ')||'Vehicle')+'</span><span class="v2-row-reg">'+esc(r.registration||'—')+'</span><b class="v2-row-next">›</b></button>').join('')||'<p class="muted">No matching Parts Lists.</p>'}
async function bucketOpen(button){const no=button?.dataset?.list;if(!no)return;await hydrateAuthoritativeLists();openList(no)}
function waitingStage(item){const s=String(item?.status||'LISTED');if(s==='LISTED')return 0;if(['ENQUIRY','QUOTED'].includes(s))return 1;if(s==='ORDERED')return 2;if(['RECEIVED','SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(s))return 3;return 0}
function waitingSteps(item){const stage=waitingStage(item),labels=['Listed','Enquiry','Ordered','Received'];return '<div class="v2-sp-wait-steps">'+labels.map((x,i)=>'<span class="'+(i<=stage?'done':'')+'">'+(i<=stage?'✓ ':'')+x+'</span>').join('')+'</div>'}
function waitingCorrection(list,item){const r=role(),s=String(item.status||'LISTED');if(!['Purchaser','Manager'].includes(r)||item.syncConflict||pendingTransition(item))return '';const back=s==='ENQUIRY'?'LISTED':s==='ORDERED'?'ENQUIRY':s==='RECEIVED'?'ORDERED':'';if(!back)return '';return '<button class="v2-sp-correct" data-list="'+esc(list.listNo)+'" data-item="'+esc(item.id)+'" data-to="'+back+'" onclick="zukaitV2.sparePartsMain.correctWaitingStatus(this)">↶ Correct</button>'}
