function arrivalPendingCount(rows=read()){return (rows||[]).reduce((n,list)=>n+arrivalPendingItems(list).length,0)}
async function confirmArrival(button){if(!button)return;const listNo=button.dataset.list,itemId=button.dataset.item;if(!['Supervisor','Manager'].includes(role()))return alert('Only Supervisor or Manager can confirm arrived parts.');await hydrateAuthoritativeLists();const list=read().find(x=>String(x.listNo)===String(listNo)),item=list?.items?.find(x=>String(x.id)===String(itemId));if(!item)return alert('Part not found.');if(String(item.status||'')!=='RECEIVED')return openArrivalConfirmation();if(!receiptComplete(item))return alert('Receipt is incomplete. Receive the remaining quantity before Supervisor confirmation.');if(!window.confirm('Confirm '+item.name+' as physically arrived?'))return;button.disabled=true;const moved=await transitionItem(listNo,itemId,'SUPERVISOR_VERIFIED','Arrival confirmed from dashboard');if(!moved.ok){button.disabled=false;return alert(moved.reason)}return openArrivalConfirmation()}
