async function render(){if(!canOpen()){alert('Spare Parts access unavailable.');return}if(role()==='Manager')return renderManagerDashboard();if(role()==='Supervisor')return renderSupervisorDashboard();if(role()==='Purchaser')return renderPurchaserDashboard();const allRows=await hydrateAuthoritativeLists(),rows=roleScopedLists(allRows),roleAttention=attentionForRole(rows).length;const body=rows.length?rows.slice(0,100).map(r=>'<button class="secondary" style="width:100%;margin:5px 0;text-align:left" onclick="zukaitV2.sparePartsMain.openList(\''+esc(r.listNo)+'\')"><b>'+esc(r.listNo)+'</b> · JC '+esc(r.jobCard)+' · '+r.items.length+' part(s)</button>').join(''):'<p class="muted">No Parts Lists yet.</p>';const createBox=denterView()?'':'<p class="muted">Create a Parts List from an existing Job Card. List numbers are automatic.</p><div class="v2-sp-search"><input id="v2SpareJob" placeholder="Job Card number"><button class="blue" onclick="zukaitV2.sparePartsMain.createFromUI()">Create Parts List</button></div><hr>';const report=role()==='Manager'?'<button class="blue" style="width:100%;margin:8px 0" onclick="zukaitV2.sparePartsMain.openManagerReport()">📊 Spare Parts Report</button>':'';const html='<h3>🔩 Spare Parts</h3><button style="'+spareBtn(roleAttention?'wait':'neutral')+';width:100%;text-align:left;margin-bottom:10px" onclick="zukaitV2.sparePartsMain.openAttention()">⚠ Needs your attention <strong style="float:right">'+roleAttention+'</strong></button>'+report+createBox+body;if(typeof window.openModal==='function')openSpareModal(withNav(html,'',true))}
function openAttention(){const rows=roleScopedLists(read()),matches=attentionForRole(rows);if(role()==='Purchaser'){ensureSparePartsUiStyle();if(!document.getElementById('v296PartsAttentionStyle')){const st=document.createElement('style');st.id='v296PartsAttentionStyle';st.textContent='.v296-attention-row{width:100%;display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:9px;align-items:center;margin:7px 0;padding:10px;background:#fff;border:1px solid #f4c77a;border-left:5px solid #e79000;border-radius:14px;box-shadow:0 5px 15px #17304d12;text-align:left;color:#17304d}.v296-attention-row.red{border-color:#f3a4a4;border-left-color:#dc2626;background:#fff8f8}.v296-attention-no{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#fff0c9;color:#9a5b00;font-weight:950}.v296-attention-row.red .v296-attention-no{background:#ffe1e1;color:#b91c1c}.v296-attention-copy{display:grid;gap:2px;min-width:0}.v296-attention-copy strong{font-size:15px;overflow-wrap:anywhere}.v296-attention-copy small{font-size:10px;color:#60748d}.v296-attention-days{display:grid;place-items:center;min-width:60px;padding:7px 8px;border-radius:999px;background:#fff0c9;color:#9a5b00;font-size:11px;font-weight:950}.v296-attention-row.red .v296-attention-days{background:#ffe1e1;color:#b91c1c}.v296-attention-note{margin:6px 0 10px;padding:9px 11px;border-radius:12px;background:#fff7e6;color:#805300;font-size:12px;font-weight:800}@media(max-width:430px){.v296-attention-row{grid-template-columns:30px minmax(0,1fr) auto;padding:8px;gap:7px}.v296-attention-copy strong{font-size:13px}.v296-attention-days{min-width:52px;font-size:10px;padding:6px}}';document.head.appendChild(st)}const body=matches.map((x,i)=>{const days=x.days??attentionAgeDays(x.item,x.list),urgent=days>30||['RETURNED','UNAVAILABLE'].includes(String(x.item?.status||'').toUpperCase()),vehicle=[x.list?.vehicle,x.list?.model,x.list?.year].filter(Boolean).join(' '),status=pendingStatusLabel(x.item);return '<button class="v296-attention-row '+(urgent?'red':'')+'" onclick="zukaitV2.sparePartsMain.openList(\''+esc(x.list?.listNo||'')+'\')"><span class="v296-attention-no">'+(i+1)+'</span><span class="v296-attention-copy"><strong>'+esc(x.item?.name||'Part')+'</strong><small>'+esc(x.list?.listNo||'')+' · JC '+esc(x.list?.jobCard||'')+' · '+esc(vehicle||'Vehicle')+'</small><small>'+esc(status)+'</small></span><b class="v296-attention-days">'+days+' days</b></button>'}).join('');openSpareModal(withNav('<div class="v2-sp-status-full"><h3>⚠ Parts Attention</h3><div class="v296-attention-note">Warning: unresolved parts waiting more than '+PARTS_ATTENTION_DAYS+' days appear here. Oldest items are shown first.</div>'+(body||'<p class="muted">No parts have been waiting more than '+PARTS_ATTENTION_DAYS+' days.</p>')+'</div>','zukaitV2.sparePartsMain.open()'));markSparePartsModal();return}const seen=new Set(),cards=[];for(const x of matches){const key=String(x.list?.listNo||'');if(!key||seen.has(key))continue;seen.add(key);const count=matches.filter(y=>String(y.list?.listNo||'')===key).length;cards.push('<button class="v2-sp-attention-card" onclick="zukaitV2.sparePartsMain.openList(\''+esc(key)+'\')"><span><b>⚠ '+esc(key)+'</b><small>JC '+esc(x.list?.jobCard||'')+' · '+count+' item(s) need action</small></span><strong>'+count+'</strong></button>')}openSpareModal(withNav('<h3>⚠ Needs your attention</h3>'+(cards.join('')||'<p class="muted">Nothing needs your attention now.</p>'),'zukaitV2.sparePartsMain.open()'))}
async function createFromUI(){if(!canManage())return alert('FORBIDDEN');
const draft=draftRead(),jobCard=normalizeJobCard(draft.jobCard),items=draft.items||[];
if(!jobCard||!items.length)return draftMessage('Find a Job Card and add at least one part.');
if(!navigator.onLine||!window.zukaitCloud?.allocateSparePartList)return draftMessage('Connect to the server before creating the Parts List. Your draft is saved.');
const button=document.getElementById('v2SpDraftCreate');if(button?.disabled)return;if(button)button.disabled=true;
draftMessage('Saving parts…');
try{
 const submissionKey=draftSubmissionKey(draft),allocation=await window.zukaitCloud.allocateSparePartList(jobCard,submissionKey);
 await hydrateAuthoritativeLists();
 const rows=read(),j=job(jobCard)||{},u=currentUser()||{};
 let list=rows.find(x=>String(x.listNo)===String(allocation.list_no));
 if(!list){list={listNo:allocation.list_no,jobCard,vehicle:allocation.vehicle||j.vehicle||j.make||'',model:allocation.model||j.model||'',year:allocation.year||j.year||'',registration:allocation.registration||j.reg||j.registration||'',customer:String(j.jobType||'').toUpperCase()==='INSURANCE'?(j.insuranceCompany||''):String(j.jobType||'').toUpperCase()==='CASH'?'Cash':String(j.jobType||'').toUpperCase()==='CREDIT'?'Credit':(j.insuranceCompany||j.customerName||''),status:allocation.status||'OPEN',items:[],createdAt:allocation.created_at||new Date().toISOString(),createdBy:allocation.created_by||u.id||null,createdByRole:u.role||null,serverAllocated:true};rows.unshift(list);write(rows)}
 if(!list.serverHydrated){
  const created=await syncList(list);
  if(!created.ok&&!created.queued){
   if(created.reason!=='event_id_conflict')throw Error('List sync failed: '+created.reason);
   await hydrateAuthoritativeLists();
   const existing=read().find(x=>String(x.listNo)===String(allocation.list_no)&&x.serverHydrated);
   if(!existing)throw Error('List sync failed: '+created.reason);
   list=existing;
  }
 }
 for(const part of items){
  if(list.items.some(x=>partKey(x.name,x.partNo)===partKey(part.name,part.partNo)&&x.status!=='RETURNED'))continue;
  const added=addItem(list.listNo,part);if(!added.ok)throw Error('Part '+part.name+': '+added.reason);
  list=added.list;
  const synced=await syncAddedPart(list,list.items[list.items.length-1]);
  if(!synced.ok&&!synced.queued)throw Error('Part sync failed: '+synced.reason);
 }
 localStorage.removeItem(DRAFT_KEY);openList(list.listNo);
}catch(e){draftMessage(String(e?.code||e?.message||e)==='job_card_not_found'?'Job Card not found on server. Check its number and sync the Job Card. Your draft is saved.':'Could not finish: '+String(e?.code||e?.message||e)+'. Your draft is saved.');if(button)button.disabled=false}
}
