async function deleteItem(listNo,itemId){
 if(!canManage())return {ok:false,reason:'FORBIDDEN'};
 const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);
 if(!list)return {ok:false,reason:'LIST_NOT_FOUND'};if(list.status==='CLOSED')return {ok:false,reason:'LIST_CLOSED'};if(!item)return {ok:false,reason:'PART_NOT_FOUND'};
 if(pendingTransition(item))return {ok:false,reason:'PENDING_SYNC'};
 const at=new Date().toISOString(),revision=Number(item.editRevision||0)+1;
 const synced=await commitEvent({eventId:'spare-delete-'+itemId+'-'+revision,entityId:itemId,actorId:currentUser()?.id||null,type:'SPARE_PART_ITEM_EDITED',serverRevision:revision,payload:{partId:itemId,listNo,jobCard:list.jobCard,reason:'Removed from Parts List',before:Object.assign({},item),after:{deletedAt:at,deletedBy:currentUser()?.id||null}}});
 if(!synced.ok&&!synced.queued)return {ok:false,reason:synced.conflictMessage||'SYNC_FAILED',detail:synced.reason};
 rememberDeleted(itemId,at);write(read());return {ok:true,queued:!!synced.queued};
}
