async function acceptArrival(listNo,itemId){if(role()!=='Purchaser')return;if(!navigator.onLine)return alert('Connect to the server to confirm final arrival.');await hydrateAuthoritativeLists();const list=read().find(x=>x.listNo===listNo),item=list?.items?.find(x=>x.id===itemId);if(!item||item.arrivalAccepted||item.syncConflict||pendingTransition(item))return;if(!['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED'].includes(String(item.status||'')))return alert('Wait for Supervisor verification before final arrival confirmation.');if(!window.confirm('Confirm '+item.name+' was checked and accepted?'))return;const eventId='spare-arrival-accepted-'+itemId,done=await commitEvent({eventId,entityId:itemId,actorId:currentUser()?.id||null,type:'SPARE_PART_ARRIVAL_ACCEPTED',serverRevision:1,payload:{partId:itemId,listNo,jobCard:list.jobCard}});if(!done.ok)return alert(done.queued?'Final confirmation is waiting for sync. The list will move after the server receives it.':(done.conflictMessage||('Could not confirm arrival: '+done.reason)));item.arrivalAccepted=true;item.arrivalAcceptedAt=new Date().toISOString();write(read().map(r=>r.listNo===listNo?list:r));openList(listNo)}
