const PENDING_DONE=new Set(['SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED','CUSTOMER_SETTLEMENT']);
function isDeliveredVehiclePartPending(item){return !!item&&!['RECEIVED','SUPERVISOR_VERIFIED','DENTER_CHECKED','SUPERVISOR_CONFIRMED','FITTED','CUSTOMER_SETTLEMENT'].includes(String(item.status||'LISTED').toUpperCase())}
function isPartPending(item){return !!item&&!PENDING_DONE.has(String(item.status||'LISTED').toUpperCase())}
function pendingQty(item){if(!isPartPending(item))return 0;const q=Number(item.qty||0),received=Number(item.receivedQty||0);const remaining=q-Math.max(0,Number.isFinite(received)?received:0);return Number.isFinite(remaining)&&remaining>0?remaining:0}
function pendingSince(item,list){return item?.returnedAt||item?.createdAt||list?.createdAt||list?.updatedAt||''}
function pendingAgeDays(item,list){const d=Date.parse(pendingSince(item,list));return Number.isFinite(d)?Math.max(0,Math.floor((Date.now()-d)/86400000)):0}
function pendingStatusLabel(item){const s=String(item?.status||'LISTED').toUpperCase();return ({LISTED:'New',ENQUIRY:'Enquiry',QUOTED:'Quoted',ORDERED:'Ordered',RECEIVED:'Arrived – Awaiting Supervisor',RETURNED:'Returned / Re-order',UNAVAILABLE:'Unavailable'})[s]||s.replace(/_/g,' ')}
function pendingLists(rows=read()){return rows.map(list=>{const items=(list.items||[]).filter(isPartPending);return items.length?{list,items,pendingQty:items.reduce((n,x)=>n+pendingQty(x),0),oldestDays:Math.max(...items.map(x=>pendingAgeDays(x,list)))}:null}).filter(Boolean).sort((a,b)=>b.oldestDays-a.oldestDays||String(a.list.listNo||'').localeCompare(String(b.list.listNo||'')))}
function pendingSummary(rows=read()){const groups=pendingLists(rows),items=groups.flatMap(x=>x.items),arrived=items.filter(x=>String(x.status||'')==='RECEIVED').length;return {vehicles:groups.length,parts:items.reduce((n,x)=>n+pendingQty(x),0),arrivedAwaiting:arrived,oldestDays:groups.reduce((m,x)=>Math.max(m,x.oldestDays),0)}}
function pendingVehicleLabel(list){const raw=[list?.vehicle,list?.model].filter(Boolean).map(v=>String(v).trim()).filter(Boolean),parts=[];for(const value of raw){const upper=value.toUpperCase(),exists=parts.some(x=>{const xu=x.toUpperCase();return xu===upper||xu.endsWith(' '+upper)||upper.endsWith(' '+xu)});if(!exists)parts.push(value)}if(list?.year)parts.push(String(list.year).trim());return parts.join(' ')||'Vehicle'}
function pendingSearchRows(){const host=document.getElementById('v2SpPendingRows');if(!host)return;const q=String(document.getElementById('v2SpPendingSearch')?.value||'').trim().toLowerCase();const groups=pendingLists().filter(x=>!q||[x.list.listNo,x.list.jobCard,x.list.registration,x.list.vehicle,x.list.model,x.list.year].some(v=>String(v||'').toLowerCase().includes(q)));host.innerHTML=groups.slice(0,200).map((x,i)=>'<button type="button" class="v2-sp-result-card v203-pending-row" data-list="'+esc(x.list.listNo)+'" onclick="zukaitV2.sparePartsMain.pendingOpenClick(this)"><span class="v203-pending-main"><b class="v203-pending-index">'+(i+1)+'</b><span class="v203-pending-copy"><strong>'+esc(x.list.listNo)+' · JC '+esc(x.list.jobCard)+'</strong><small>'+esc(pendingVehicleLabel(x.list))+' · Reg '+esc(x.list.registration||'—')+'</small><em class="v271-pending-age '+(x.oldestDays>=6?'danger':x.oldestDays>=3?'warn':'fresh')+'">'+x.pendingQty+' Pending · '+x.oldestDays+' Day'+(x.oldestDays===1?'':'s')+'</em></span></span><strong class="v203-pending-arrow">›</strong></button>').join('')||'<div class="v2-sp-empty">No matching pending parts.</div>'}
function pendingOpenClick(button){const no=button?.dataset?.list;if(no)openPendingList(no)}
