function pendingText(no){const r=pendingListRecord(no);if(!r)return '';const vehicle=[r.list.vehicle,r.list.model,r.list.year].filter(Boolean).join(' ');return ['*PARTS PENDING LIST*','PL: '+r.list.listNo,'JC: '+r.list.jobCard,'Vehicle: '+(vehicle||'—'),'Registration: '+(r.list.registration||'—'),'','Remaining Parts:',...r.items.map((x,i)=>(i+1)+'. '+(x.name||'Part')+' — Pending '+pendingQty(x)+' — '+pendingStatusLabel(x))].join('\n')}
