async function syncAddedPart(list,item){
const eventId='spare-item-'+item.id;item.pendingSync=true;item.pendingEventId=eventId;
write(read().map(r=>r.listNo===list.listNo?list:r));
const result=await commitEvent({eventId,entityId:item.id,actorId:currentUser()?.id||null,type:'SPARE_PART_LISTED',serverRevision:1,payload:{partId:item.id,listNo:list.listNo,jobCard:list.jobCard,name:item.name,partNo:item.partNo,qty:item.qty,targetRole:'Purchaser'}});
if(result.ok){delete item.pendingSync;delete item.pendingEventId;write(read().map(r=>r.listNo===list.listNo?list:r))}
else if(!result.queued&&!result.conflictMessage){list.items=list.items.filter(x=>x.id!==item.id);write(read().map(r=>r.listNo===list.listNo?list:r))}
return result;
}
async function addFromUI(no){if(!canManage())return alert('FORBIDDEN');
const name=String(document.getElementById('v2PartName')?.value||'').trim(),qty=validQty(document.getElementById('v2PartQty')?.value);
if(!name)return alert('Enter the required part name.');if(qty==null)return alert('Enter a valid quantity.');
const button=document.getElementById('v2PartAdd');if(button?.disabled)return;if(button)button.disabled=true;
try{
 if(navigator.onLine){
  await hydrateAuthoritativeLists();
  const fresh=read().find(x=>x.listNo===no),duplicate=fresh?.items?.find(x=>partKey(x.name,x.partNo)===partKey(name,'')&&x.status!=='RETURNED');
  if(duplicate)return alert('This part is already on the Parts List. The latest server data has been loaded.');
 }
 const r=addItem(no,{name,qty});if(!r.ok)return alert(r.reason==='DUPLICATE_PART'?'This part is already on the Parts List.':r.reason);
 const synced=await syncAddedPart(r.list,r.list.items[r.list.items.length-1]);
 if(!synced.ok&&!synced.queued)return alert(synced.conflictMessage||('Could not save additional part: '+synced.reason+'.'));
 if(synced.queued)alert('Additional part saved on this device and waiting for server sync.');
 openList(no);return {ok:true,queued:!!synced.queued};
}finally{if(button)button.disabled=false}
}
